<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Ticket report</h1><p class="text-secondary mb-0"><?= (int) $total ?> matching tickets, scoped to your access.</p></div><a class="btn btn-outline-primary" href="<?= site_url('reports/export.csv') . ($queryString ? '?' . esc($queryString) : '') ?>">Export CSV</a></div>
<form class="card card-body mb-3" method="get"><div class="row g-2"><div class="col-lg-3"><label class="visually-hidden" for="q">Search</label><input class="form-control" id="q" name="q" placeholder="Ticket or subject" value="<?= esc($filters['q']) ?>"></div><div class="col-6 col-lg"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach (['Open','In Progress','Resolved','Closed'] as $v): ?><option value="<?= esc($v) ?>" <?= $filters['status'] === $v ? 'selected' : '' ?>><?= esc($v) ?></option><?php endforeach ?></select></div><div class="col-6 col-lg"><select class="form-select" name="priority"><option value="">All priorities</option><?php foreach (['Low','Medium','High'] as $v): ?><option value="<?= esc($v) ?>" <?= $filters['priority'] === $v ? 'selected' : '' ?>><?= esc($v) ?></option><?php endforeach ?></select></div><div class="col-6 col-lg"><select class="form-select" name="category"><option value="">All categories</option><?php foreach ($categories as $c): ?><option value="<?= (int) $c['id'] ?>" <?= $filters['category'] === (string) $c['id'] ? 'selected' : '' ?>><?= esc($c['name']) ?></option><?php endforeach ?></select></div><div class="col-6 col-lg"><label class="visually-hidden" for="from">From</label><input class="form-control" id="from" type="date" name="from" value="<?= esc($filters['from']) ?>"></div><div class="col-6 col-lg"><label class="visually-hidden" for="to">To</label><input class="form-control" id="to" type="date" name="to" value="<?= esc($filters['to']) ?>"></div><div class="col-6 col-lg-auto"><button class="btn btn-outline-primary">Filter</button></div></div></form>
<div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Ticket</th><th>Subject</th><th>Category</th><th>Priority</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach ($tickets as $ticket): ?><tr><td><a href="<?= site_url('tickets/' . $ticket['id']) ?>"><?= esc($ticket['ticket_number']) ?></a></td><td><?= esc($ticket['subject']) ?></td><td><?= esc($ticket['category_name']) ?></td><td><?= esc($ticket['priority']) ?></td><td><?= esc($ticket['status']) ?></td><td><?= esc($ticket['created_at']) ?></td></tr><?php endforeach ?><?php if (! $tickets): ?><tr><td colspan="6" class="text-center text-secondary py-4">No matching tickets.</td></tr><?php endif ?></tbody></table></div></div>
<?php if ($total > 20): ?><nav class="mt-3" aria-label="Report pages"><ul class="pagination justify-content-end"><li class="page-item <?= $pageNumber <= 1 ? 'disabled' : '' ?>"><a class="page-link" href="<?= current_url(true)->setQueryArray(array_merge($filters, ['page' => max(1, $pageNumber - 1)])) ?>">Previous</a></li><li class="page-item <?= $pageNumber * 20 >= $total ? 'disabled' : '' ?>"><a class="page-link" href="<?= current_url(true)->setQueryArray(array_merge($filters, ['page' => $pageNumber + 1])) ?>">Next</a></li></ul></nav><?php endif ?>
